// The stairs wave, part B: how each stair clip's window was chosen (src/anim/stairCycle.ts's `STAIR_WINDOWS`), the very
// search the table was generated by and `stairCycles.test.ts` runs again. Over a grid of a sixtieth of a second, every
// window long enough to hold the clip's step (two footfalls: three quarters of the clip at least; one footfall: half of
// it, and the footfall inside it), the one whose seam before it is spread is least: the legs' worst point against the
// hips (metres) and a twentieth of a second of their speeds' worst (so a seam that meets but turns back costs as much as
// one 5 cm apart per m/s). Not a test itself.
import type * as THREE from 'three';
import type { TargetSkeleton } from '../../../src/anim/fit.ts';
import { measureCycle, windowSeam, type StairWindow } from '../../../src/anim/stairCycle.ts';

/** A second of speed's worth of the seam's cost, seconds. */
export const VEL_WEIGHT = 0.05;
/** The grid, seconds. */
export const GRID = 1 / 60;

/** The best window for a clip: one footfall or two. */
export function searchWindow(clip: THREE.AnimationClip, skel: TargetSkeleton, one: boolean): StairWindow {
  const T = clip.duration;
  const least = one ? 0.5 * T : 0.75 * T;
  const fall = one ? measureCycle(clip, skel, 1) : null;
  const fallAt = fall ? fall.at[0] : Number.NaN;
  let best: StairWindow = { t0: 0, t1: T, one, seamMm: Infinity, seamVel: Infinity };
  let bestCost = Infinity;
  const n = Math.round(T / GRID);
  for (let a = 0; a <= n; a++) {
    const t0 = Math.min(T, a * GRID);
    for (let c = a + 1; c <= n; c++) {
      const t1 = c === n ? T : c * GRID;
      if (t1 - t0 < least - 1e-9) continue;
      if (one && fallAt === fallAt && !(fallAt >= t0 - 1e-9 && fallAt <= t1 + 1e-9)) continue;
      const s = windowSeam(clip, skel, t0, t1, one);
      const cost = s.gap + VEL_WEIGHT * s.vel;
      if (cost < bestCost) {
        bestCost = cost;
        best = { t0: Number(t0.toFixed(3)), t1: Number(t1.toFixed(3)), one, seamMm: Number((s.gap * 1000).toFixed(1)), seamVel: Number(s.vel.toFixed(3)) };
      }
    }
  }
  return best;
}
